"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([["46192"],{64387(e,n,t){t.r(n),t.d(n,{metadata:()=>o,default:()=>u,frontMatter:()=>s,contentTitle:()=>r,toc:()=>l,assets:()=>h});var o=JSON.parse('{"id":"qiangguo/oldforold","title":"","description":"Girl Who Likes Mathematics","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/qiangguo/oldforold.md","sourceDirName":"qiangguo","slug":"/qiangguo/oldforold","permalink":"/en/qiangguo/oldforold","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"oldforold","title":"","hide_table_of_contents":true,"sidebar_label":"He Xin, Don\'t Use Age to Sell Age, or Ignorance to Sell Ignorance!"},"sidebar":"qiangguoSidebar","previous":{"title":"So-Called STEM Thinking Is Nothing But a Variant of Theological Thinking","permalink":"/en/qiangguo/engineeringthinking"},"next":{"title":"He Xin\'s \\"Illness\\" and the Corresponding \\"Medicine\\" (A Serious Discussion, Please Allow Publication)","permalink":"/en/qiangguo/hexinproblemandsolution"}}'),i=t(74848),a=t(28453);let s={id:"oldforold",title:"",hide_table_of_contents:!0,sidebar_label:"He Xin, Don't Use Age to Sell Age, or Ignorance to Sell Ignorance!"},r="He Xin, Stop Trading on Your Age and Trading on Your Ignorance!",h={},l=[];function d(e){let n={blockquote:"blockquote",h1:"h1",header:"header",p:"p",...(0,a.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(n.header,{children:(0,i.jsx)(n.h1,{id:"he-xin-stop-trading-on-your-age-and-trading-on-your-ignorance",children:"He Xin, Stop Trading on Your Age and Trading on Your Ignorance!"})}),"\n",(0,i.jsxs)(n.blockquote,{children:["\n",(0,i.jsx)(n.p,{children:"Girl Who Likes Mathematics"}),"\n"]}),"\n",(0,i.jsx)(n.p,{children:'This He Xin has always traded on his seniority and traded on his ignorance. Today I again came across his "On the Classical Spirit of Chinese Painting and the Decline of Contemporary Painting Style" (preface to "He Xin\'s Painting Collection"), and the same old problems persist. Since this gentleman has devoted himself to the lineage of Chan painting from the transition between the Southern Song and Yuan -- Yujian, Wen Riguan, and Muqi -- he naturally must show off his knowledge of Chan Buddhism. Laughably, he writes: "In Buddhism, human problems are divided into three realms for consideration. First is the desire realm, second is the form realm where desires are more attenuated, and finally the formless realm where both desire and form have vanished, which is the realm of enlightenment (Buddha). What Chan Buddhism focuses on is precisely liberation from the desire realm and form realm to attain the state of the formless realm." The error here is the most basic kind of common knowledge -- one that even an ordinary old grandmother wouldn\'t commit. The formless realm equals the Buddha realm? Chan Buddhism focuses on entering the formless realm? Even when an Arhat enters the cessation absorption, they have already transcended the highest heaven of the formless realm -- the Heaven of Neither Perception Nor Non-Perception. Not knowing something this kindergarten-level and still daring to wave the Chan Buddhism flag?'}),"\n",(0,i.jsx)(n.p,{children:'The next error is slightly more advanced. Due to the later erosion of Chan by Laozi-Zhuangzi thought, virtually everyone conflates Chan Buddhism with Laozi and Zhuangzi, spouting nonsense about Chan being sinicized, Laozi-Zhuangzi-ized Buddhism, and other such rubbish. Since this gentleman dares to commit even kindergarten-level errors like the above, the following mistake is hardly surprising: "And ascending one pass from the study of Zhuangzi, one glimpses the workings of Chan." Such Chan Buddhism is truly feeble and tangled.'}),"\n",(0,i.jsx)(n.p,{children:"This gentleman also has another problem: the more ignorant he is, the more fearless. He says things like \"wild fox\" actually just means \"talking nonsense.\" Well then, since you're talking nonsense, let's see how things look on the last day of the twelfth month. Let's see whether it's nonsense or fox-sense."}),"\n",(0,i.jsx)(n.p,{children:'This young lady very seriously requests that this gentleman stop talking nonsense henceforth. When the time comes, wanting to be a "hu" (nonsense) will turn you into a "hu" (fox). He also says things like: "The reason Chan Buddhism positions itself outside the teachings, transmitting only the mind-seal, not establishing language or written words, is also to break through the obstacle of apophatic definition." But when has apophatic definition ever been an obstacle? Do not let diseased eyes produce phantom flowers. I request that old Mr. He Xin first study the koan of Jiashan meeting the Boatman, then look at the koan of Deshao meeting Fayan. Matters of the ancestral school are weighty -- do not make a mess of the lineage.'})]})}function u(e={}){let{wrapper:n}={...(0,a.R)(),...e.components};return n?(0,i.jsx)(n,{...e,children:(0,i.jsx)(d,{...e})}):d(e)}},28453(e,n,t){t.d(n,{R:()=>s,x:()=>r});var o=t(96540);let i={},a=o.createContext(i);function s(e){let n=o.useContext(a);return o.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function r(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:s(e.components),o.createElement(a.Provider,{value:n},e.children)}}}]);